#include "test_common.h"
#include "authentication.h"
static BmsUser_t make_user(BmsUserId_t id,const char *name,BmsUserRole_t role){BmsUser_t u;memset(&u,0,sizeof u);u.userId=id;snprintf(u.username,sizeof u,"%s",name);u.role=role;u.status=BMS_USER_STATUS_ACTIVE;u.isActive=true;return u;}
static void test_register_login_duplicate(void){BmsAuthenticationContext_t c;BmsUser_t u=make_user(1U,"admin01",BMS_ROLE_ADMIN),out;ASSERT_OK(AuthenticationInitialize(&c));ASSERT_OK(AuthenticationRegisterUser(&c,&u,"Strong@123"));ASSERT_STATUS(BMS_STATUS_ALREADY_EXISTS,AuthenticationRegisterUser(&c,&u,"Strong@123"));ASSERT_OK(AuthenticationLogin(&c,"admin01","Strong@123",&out));CU_ASSERT_EQUAL(out.userId,1U);ASSERT_STATUS(BMS_STATUS_AUTHENTICATION_FAILED,AuthenticationLogin(&c,"admin01","Wrong@123",&out));AuthenticationDeinitialize(&c);}
static void test_lookup_next_role(void){BmsAuthenticationContext_t c;BmsUser_t u=make_user(1U,"staff01",BMS_ROLE_BLOOD_BANK_STAFF),out;BmsUserId_t next=0U;ASSERT_OK(AuthenticationInitialize(&c));ASSERT_OK(AuthenticationRegisterUser(&c,&u,"Strong@123"));ASSERT_OK(AuthenticationFindUserById(&c,1U,&out));ASSERT_OK(AuthenticationFindUserByUsername(&c,"staff01",&out));ASSERT_OK(AuthenticationGetNextUserId(&c,&next));CU_ASSERT_EQUAL(next,1001U);CU_ASSERT_TRUE(AuthenticationHasRole(&out,BMS_ROLE_BLOOD_BANK_STAFF));CU_ASSERT_FALSE(AuthenticationHasRole(&out,BMS_ROLE_ADMIN));AuthenticationDeinitialize(&c);}
static void test_password_recovery_status(void){BmsAuthenticationContext_t c;BmsUser_t u=make_user(1U,"donor01",BMS_ROLE_DONOR),out;ASSERT_OK(AuthenticationInitialize(&c));ASSERT_OK(AuthenticationRegisterUser(&c,&u,"Strong@123"));ASSERT_OK(AuthenticationSetRecoveryCode(&c,1U,"Recover@123"));ASSERT_OK(AuthenticationChangePassword(&c,1U,"Strong@123","NewStrong@1"));ASSERT_OK(AuthenticationLogin(&c,"donor01","NewStrong@1",&out));ASSERT_OK(AuthenticationResetPassword(&c,"donor01","Recover@123","ResetStrong@1"));ASSERT_OK(AuthenticationSetUserStatus(&c,1U,BMS_USER_STATUS_DISABLED));ASSERT_STATUS(BMS_STATUS_ACCESS_DENIED,AuthenticationLogin(&c,"donor01","ResetStrong@1",&out));AuthenticationDeinitialize(&c);}
void RegisterAuthenticationTests(void){CU_pSuite s=CU_add_suite("Authentication",NULL,NULL);CU_add_test(s,"register login duplicate",test_register_login_duplicate);CU_add_test(s,"lookup next ID role",test_lookup_next_role);CU_add_test(s,"password recovery status",test_password_recovery_status);}
